CREATE OR REPLACE FUNCTION public.dedupe_lead_call()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.event_type = 'call' and exists (
    select 1 from public.lead_events e
    where e.lead_id = new.lead_id
      and e.event_type = 'call'
      and e.actor_id is not distinct from new.actor_id
      and e.created_at > now() - interval '2 minutes'
  ) then
    return null;
  end if;

  if new.device is null and auth.uid() is not null then
    begin
      new.device := left(nullif(current_setting('request.headers', true), '')::json->>'user-agent', 300);
    exception when others then
      null;
    end;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enqueue_automations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  auto record;
  step record;
begin
  if tg_op = 'INSERT' then
    if new.created_at >= now() - interval '30 minutes' then
      for auto in
        select id from public.automations
        where trigger_type = 'lead_created' and enabled = true
      loop
        select delay_minutes into step from public.automation_steps
          where automation_id = auto.id and step_order = 0 limit 1;
        insert into public.automation_runs (lead_id, automation_id, current_step, run_at, status)
        values (new.id, auto.id, 0,
          now() + coalesce(step.delay_minutes, 0) * interval '1 minute',
          'pending')
        on conflict (lead_id, automation_id)
          where status = any (array['pending','processing'])
          do nothing;
      end loop;
    end if;
  end if;

  if tg_op = 'UPDATE' and old.stage is distinct from new.stage then
    for auto in
      select id from public.automations
      where trigger_type = 'stage_changed'
        and enabled = true
        and (trigger_stage is null or trigger_stage = new.stage)
    loop
      select delay_minutes into step from public.automation_steps
        where automation_id = auto.id and step_order = 0 limit 1;
      insert into public.automation_runs (lead_id, automation_id, current_step, run_at, status)
      values (new.id, auto.id, 0,
        now() + coalesce(step.delay_minutes, 0) * interval '1 minute',
        'pending')
      on conflict (lead_id, automation_id)
        where status = any (array['pending','processing'])
        do nothing;
    end loop;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.find_user_id_by_phone(p_phone text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
  select id from auth.users where phone = p_phone limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_secret(secret_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pg_temp'
AS $function$
DECLARE
  result text;
BEGIN
  SELECT decrypted_secret INTO result
  FROM vault.decrypted_secrets
  WHERE name = secret_name
  LIMIT 1;
  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_operator()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE((SELECT is_operator FROM agent_profiles WHERE agent_id = auth.uid()), false);
$function$
;

CREATE OR REPLACE FUNCTION public.lead_page_funnel(p_page_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(views bigint, starts bigint, contacts bigint, disqualified bigint, submits bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select
    count(*) filter (where event_type = 'view'),
    count(*) filter (where event_type = 'start'),
    count(*) filter (where event_type = 'contact'),
    count(*) filter (where event_type = 'disqualified'),
    count(*) filter (where event_type = 'submit')
  from public.lead_page_events
  where page_id = p_page_id
    and (p_since is null or created_at >= p_since);
$function$
;

CREATE OR REPLACE FUNCTION public.record_lead_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  hdrs json;
  v_actor uuid;
  v_source text := 'system';
  v_device text;
  last_note uuid;
begin
  begin
    hdrs := nullif(current_setting('request.headers', true), '')::json;
  exception when others then
    hdrs := null;
  end;

  if auth.uid() is not null then
    v_actor := auth.uid();
    v_source := 'dashboard';
    v_device := left(hdrs->>'user-agent', 300);
  elsif coalesce(auth.role(), '') = 'service_role' then
    v_source := coalesce(nullif(hdrs->>'x-ek-source', ''), 'system');
    begin
      v_actor := nullif(hdrs->>'x-ek-actor', '')::uuid;
    exception when others then
      v_actor := null;
    end;
    v_device := left(nullif(hdrs->>'x-ek-device', ''), 300);
  end if;

  if tg_op = 'INSERT' then
    insert into public.lead_events (lead_id, agent_id, actor_id, event_type, to_value, source, device, created_at)
    values (
      new.id, new.agent_id, v_actor, 'created', new.stage,
      case
        when new.fb_lead_id is not null then 'facebook'
        when new.source_page_id is not null then 'website'
        else v_source
      end,
      v_device,
      coalesce(new.created_at, now())
    );
    return new;
  end if;

  if new.stage is distinct from old.stage then
    insert into public.lead_events (lead_id, agent_id, actor_id, event_type, from_value, to_value, source, device)
    values (new.id, new.agent_id, v_actor, 'stage_changed', old.stage, new.stage, v_source, v_device);
  end if;

  if new.pipeline_id is distinct from old.pipeline_id then
    insert into public.lead_events (lead_id, agent_id, actor_id, event_type, from_value, to_value, source, device)
    values (
      new.id, new.agent_id, v_actor, 'pipeline_moved',
      (select name from public.pipelines where id = old.pipeline_id),
      (select name from public.pipelines where id = new.pipeline_id),
      v_source, v_device
    );
  end if;

  if new.archived is distinct from old.archived then
    insert into public.lead_events (lead_id, agent_id, actor_id, event_type, source, device)
    values (new.id, new.agent_id, v_actor, case when new.archived then 'archived' else 'restored' end, v_source, v_device);
  end if;

  -- Notes autosave as you type, so fold edits by the same person within 10
  -- minutes into one entry instead of one per keystroke burst.
  if new.note is distinct from old.note then
    select id into last_note
    from public.lead_events
    where lead_id = new.id
      and event_type = 'note_changed'
      and actor_id is not distinct from v_actor
      and created_at > now() - interval '10 minutes'
    order by created_at desc
    limit 1;

    if last_note is not null then
      update public.lead_events
      set to_value = left(new.note, 2000), created_at = now(), device = coalesce(v_device, device)
      where id = last_note;
    else
      insert into public.lead_events (lead_id, agent_id, actor_id, event_type, to_value, source, device)
      values (new.id, new.agent_id, v_actor, 'note_changed', left(new.note, 2000), v_source, v_device);
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_overview_daily(p_agent_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Delete existing auto-computed rows (keep rows with manual spend)
  DELETE FROM overview_daily
  WHERE (p_agent_id IS NULL OR agent_id = p_agent_id);

  -- Insert computed rows from leads
  INSERT INTO overview_daily (agent_id, date, spend, leads, leads_reached, appts, appts_held, mandates, commission_expected, commission_earned)
  SELECT
    l.agent_id,
    (l.created_at AT TIME ZONE 'Africa/Johannesburg')::date AS dt,
    0 AS spend,
    COUNT(*) AS leads,
    COUNT(*) FILTER (WHERE l.stage NOT IN ('New Lead', 'Invalid Number')) AS leads_reached,
    COUNT(*) FILTER (WHERE l.stage IN ('Booked', 'Mandate Signed')) AS appts,
    COUNT(*) FILTER (WHERE l.stage IN ('Mandate Signed')) AS appts_held,
    COUNT(*) FILTER (WHERE l.stage = 'Mandate Signed') AS mandates,
    COALESCE(SUM(l.commission) FILTER (WHERE l.stage = 'Mandate Signed'), 0) AS commission_expected,
    COALESCE(SUM(l.commission) FILTER (WHERE l.stage = 'Mandate Signed'), 0) AS commission_earned
  FROM leads l
  WHERE (p_agent_id IS NULL OR l.agent_id = p_agent_id)
  GROUP BY l.agent_id, dt
  ORDER BY dt;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.seed_setup_steps()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.setup_steps (agent_id, key, title, sort_order, done, cta_label, cta_url, cta_filled) values
    (new.id, 'signed_up',   'You''re signed up',       1, true,  null,          null,                               false),
    (new.id, 'setup_call',  'Setup call booked',        2, false, 'Book',       'https://cal.com',                  false),
    (new.id, 'connect_fb',  'Connect your Facebook',    3, false, 'Connect',    'https://business.facebook.com',    true),
    (new.id, 'go_live',     'Go live on your call',     4, false, 'View',       'https://business.facebook.com/adsmanager', false);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;


