select cron.schedule('daily-stage-nudge-weekdays', '0 14 * * 1-5', '
  select net.http_post(
    url := ''https://yfcnsvrhojpysrzqrkdi.supabase.co/functions/v1/daily-stage-nudge'',
    headers := ''{"Content-Type": "application/json"}''::jsonb,
    body := ''{}''::jsonb
  );
  '); select cron.alter_job(job_id := (select jobid from cron.job where jobname = 'daily-stage-nudge-weekdays'), active := false);

select cron.schedule('run-automations-every-minute', '* * * * *', '
  select net.http_post(
    url := ''https://yfcnsvrhojpysrzqrkdi.supabase.co/functions/v1/run-automations'',
    headers := ''{"Content-Type": "application/json"}''::jsonb,
    body := ''{}''::jsonb
  );
  ');

select cron.schedule('sync-fb-leads-every-5-min', '*/15 * * * *', '
  select net.http_post(
    url := ''https://yfcnsvrhojpysrzqrkdi.supabase.co/functions/v1/sync-fb-leads'',
    headers := ''{"Content-Type": "application/json"}''::jsonb,
    body := ''{"sinceDays": 3, "includePageForms": true}''::jsonb
  );
  ');


-- ==========================================================================
-- 17. Comments
-- ==========================================================================

comment on column public.agent_profiles.avatar_url is 'The agent''s face. sidebar_logo_url stays the agency/brand mark.';

comment on column public.custom_questions.low_quality_answers is 'Answers that still create a lead but are not reported to Facebook as a conversion. Distinct from disqualify_answers, which creates no lead at all.';

comment on column public.lead_pages.fb_page_id is 'The Facebook page this source''s form lives on. Null means "the agent''s own page" (agent_profiles.fb_page_id), which is correct for almost every source.';

comment on column public.leads.attribution is 'Ad/traffic attribution captured on the landing page at first visit: utm_*, fbclid, ad_id, campaign_id, referrer. Empty for leads with no captured source.';

comment on column public.leads.commission_received_at is 'When the commission was actually banked. Null = still only expected. Only leads with this set count toward earned commission on the Overview.';

